export class RetrySchedule {
  private attempts = 0
  private delayMillis: number

  constructor(delayMillis: number) {
    this.delayMillis = delayMillis
  }

  static immediate(): RetrySchedule {
    return new RetrySchedule(0)
  }

  get delay(): number {
    return this.delayMillis
  }

  set delay(value: number) {
    this.delayMillis = Math.max(0, value)
  }

  nextDelay(): number {
    const delay = this.delayMillis * 2 ** this.attempts
    this.attempts += 1
    return delay
  }

  reset(): void {
    this.attempts = 0
  }
}
